class Solution:
    def componentValue(self, nums: List[int], edges: List[List[int]]) -> int:
        tree = [[] for _ in range(len(nums))]
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        def dfs(u, p, target):
            cur = nums[u]
            for v in tree[u]:
                if v != p:
                    cur += dfs(v, u, target)
            return 0 if cur == target else cur

        total = sum(nums)
        for k in range(1, total // 2 + 1):
            if total % k != 0:
                continue
            target = total // k
            if dfs(0, -1, target) == 0:
                return k - 1
        return 0

