from typing import List

class Solution:
    def canThreePartsEqualSum(self, arr: List[int]) -> bool:
        total = sum(arr)
        if total % 3 != 0:
            return False
        each_sum = total // 3
        cum_sum = 0
        parts = 0
        for x in arr:
            cum_sum += x
            if cum_sum == each_sum and parts < 2:
                cum_sum = 0
                parts += 1
        return parts == 2

