class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # build trie of forbidden words
        trie = {}
        for f in forbidden:
            t = trie
            for c in f:
                if c not in t:
                    t[c] = {}
                t = t[c]
            t["end"] = True

        # returns length of a forbidden prefix, 0 if none
        def isForbidden(s: str) -> int:
            t = trie
            length = 0
            for c in s:
                if c not in t:
                    return 0
                t = t[c]
                length += 1
                if "end" in t:
                    return length
            return 0

        res = 0
        j = len(word)                     # end of current window
        for i in range(len(word) - 1, -1, -1):
            length = isForbidden(word[i:j])
            if length:                     # a forbidden substring starts at i
                j = i - length              # move window start past it
            res = max(res, j - i)           # current valid length
        return res

