class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        from functools import lru_cache

        def inline(x):
            return len(str(x)) + 1 if x > 1 else (1 if x else 0)

        @lru_cache(None)
        def dfs(i, prev, cnt, left):
            if left < 0:          # no deletions left, but still have to process
                return float('inf')
            if i == len(s):       # reached end of string
                return inline(cnt)
            # delete current character
            delete = dfs(i + 1, prev, cnt, left - 1)
            # keep current character
            if s[i] == prev:
                keep = dfs(i + 1, prev, cnt + 1, left)
            else:
                keep = dfs(i + 1, s[i], 1, left)
            return min(delete, keep)

        return dfs(0, '', 0, k)

