from typing import List

class Solution:
    def restoreIpAddresses(self, s: str) -> List[str]:
        res, cur = [], []
        def backtrack(start: int):
            if len(cur) == 4:
                if start == len(s):
                    res.append(".".join(cur))
                return
            if start == len(s):
                return
            for l in range(1, 4):
                if start + l > len(s):
                    break
                segment = s[start:start + l]
                if (segment[0] == '0' and l > 1) or int(segment) > 255:
                    continue
                cur.append(segment)
                backtrack(start + l)
                cur.pop()
        backtrack(0)
        return res

