    def _cdist(self, it: int, dist_array: List[List[int]], dist_idx: int, edges: List[int]) -> List[int]:
        rdist = 0
        nodes = []
        while it != -1 and dist_array[it][dist_idx] > rdist:
            dist_array[it][dist_idx] = rdist
            nodes.append(it)
            it = edges[it]
            rdist += 1
        return nodes

    def closestMeetingNode(self, edges: List[int], node1: int, node2: int) -> int:
        INF = float('inf')
        dist = defaultdict(lambda: [INF, INF])
        mmin, ans = INF, INF
        d1 = self._cdist(node1, dist, 0, edges)
        d2 = self._cdist(node2, dist, 1, edges)
        for k in set(d1) | set(d2):
            m = max(dist[k])
            if m != INF:
                if m < mmin:
                    mmin, ans = m, k
                elif m == mmin:
                    ans = min(ans, k)
        return ans if ans != INF else -1

