class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9+7
        n = len(s)
        dp = [1]*(n+1)
        for i,ch in enumerate(s):
            new = [0]*(n-i)
            if ch == 'I':
                pref=0
                for j in range(i+1):
                    pref=(pref+dp[j])%MOD
                    new[j]=pref
            else:
                suff=0
                for j in range(i,-1,-1):
                    suff=(suff+dp[j])%MOD
                    new[j]=suff
            dp=new
        return dp[0]%MOD

