class Solution:
    MOD = 10**9 + 7

    def ways(self, pizza, k):
        m, n = len(pizza), len(pizza[0])
        pref = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m):
            for j in range(n):
                pref[i + 1][j + 1] = pref[i][j + 1] + pref[i + 1][j] - pref[i][j] + (pizza[i][j] == 'A')

        from functools import lru_cache

        @lru_cache(None)
        def dp(r, c, kk):
            if pref[m][n] - pref[r][c] < kk:
                return 0
            if kk == 1:
                return 1
            ans = 0
            for nr in range(r + 1, m):
                if pref[nr][n] - pref[r][n] - (pref[nr][c] - pref[r][c]) > 0:
                    ans = (ans + dp(nr, c, kk - 1)) % self.MOD
            for nc in range(c + 1, n):
                if pref[m][nc] - pref[r][nc] - (pref[m][c] - pref[r][c]) > 0:
                    ans = (ans + dp(r, nc, kk - 1)) % self.MOD
            return ans

        return dp(0, 0, k) % self.MOD

