class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        s1_f = [c for c in s1 if c in s2]
        len1, len2 = len(s1_f), len(s2)
        state = {}
        i = j = 0
        repeats = 0
        for k in range(1, n1+1):
            i += len1
            while i>0:
                if s1_f[(i-1)%len1] == s2[j%len2]:
                    j+=1
                    if j%len2==0:
                        repeats+=1
                i-=1
            key = (i%len1, j%len2)
            if key in state:
                prev_repeat = state[key][0]
                cycle = repeats - prev_repeat
                total = prev_repeat + ((n1 - k)//cycle)*cycle
                return total//n2
            state[key] = (repeats, k)
        return repeats//n2

