class Solution:
    def construct(self, grid: List[List[int]]) -> 'Node':
        if not grid: return None
        n = len(grid)
        return self._build(grid, 0, n, 0, n)

    def _build(self, grid, rs, re, cs, ce):
        # leaf cell
        if rs + 1 == re and cs + 1 == ce:
            return Node(grid[rs][cs], True)
        # split region
        mid_r = (re - rs) // 2
        mid_c = (ce - cs) // 2
        tl = self._build(grid, rs, rs+mid_r, cs, cs+mid_c)
        tr = self._build(grid, rs, rs+mid_r, cs+mid_c, ce)
        bl = self._build(grid, rs+mid_r, re, cs, cs+mid_c)
        br = self._build(grid, rs+mid_r, re, cs+mid_c, ce)
        # can we merge children?
        if tl.isLeaf and tr.isLeaf and bl.isLeaf and br.isLeaf \
           and tl.val == tr.val == bl.val == br.val:
            return Node(tl.val, True)
        # otherwise internal node
        return Node(tl.val, False, tl, tr, bl, br)

