class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        ptr2 = cnt = repeat = 0
        pattern = {}
        while repeat < n1:
            for ch in s1:
                if ch == s2[ptr2]:
                    ptr2 += 1
                    if ptr2 == len(s2):
                        cnt += 1
                        ptr2 = 0
                repeat += 1
            if ptr2 in pattern:
                prev = pattern[ptr2]
                cycle = repeat - prev
                cnt += (n1 - repeat) // cycle * cnt
                break
            pattern[ptr2] = repeat
        return cnt // n2

