class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        toppingCosts = [c * 2 for c in toppingCosts]

        @lru_cache(None)
        def dfs(i, rem):
            if rem < 0 or i == len(toppingCosts):
                return 0
            take = dfs(i + 1, rem - toppingCosts[i])
            skip = dfs(i + 1, rem)
            return min([skip, toppingCosts[i] + take], key=lambda y: (abs(y - rem), y))

        ans = inf
        for bc in baseCosts:
            ans = min([ans, bc + dfs(0, target - bc)], key=lambda y: (abs(y - target), y))
