class Solution:
    def smallestString(self, s: str) -> str:
        if not s:
            return s
        # if all characters are identical and not only 'a'
        if len(set(s)) == 1 and 'a' not in s:
            return ''.join(chr(ord(c) - 1) for c in s)
        # count leading 'a's
        i = 0
        while i < len(s) and s[i] == 'a':
            i += 1
        # shift the rest of the string backwards
        shifted = ''.join(chr(ord(ch) - 1) if ch != 'a' else 'z' for ch in s[i:])
        return s[:i] + shifted

