                    idx += 1
                    if idx == len(s2):
                        cnt += 1
                        idx = 0
            if idx in pos:
                pi, pc = pos[idx]
                cycle_len = i - pi
                cycle_cnt = cnt - pc
                repeat = (n1 - i - 1) // cycle_len
                cnt += cycle_cnt * repeat
                i += cycle_len * repeat
                break
            pos[idx] = (i, cnt)
            i += 1
        # finish the remaining repetitions
        for _ in range(i+1, n1):
            for ch in s1:
                if ch == s2[idx]:
                    idx += 1
                    if idx == len(s2):
                        cnt += 1
                        idx = 0
        return cnt // n2

