class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        n = len(lcp)
        # validation
        for i in range(n):
            for j in range(i+1, n):
                if lcp[i][j] != lcp[j][i]:
                    return ''
                if lcp[i][j] > n - j:
                    return ''
        for i in range(n):
            if lcp[i][i] != n - i:
                return ''
        # build groups
        pattern = [-1] * n
        cur = 0
        for i in range(n):
            if pattern[i] != -1:
                continue
            pattern[i] = cur
            for j in range(i+1, n):
                if lcp[i][j] > 0:
                    if pattern[j] != -1 and pattern[j] != cur:
                        return ''
                    pattern[j] = cur
            cur += 1
        # verify lcp matches generated groups
        for i in range(n):
            for j in range(n):
                same = pattern[i] == pattern[j]
                val = n - max(i, j) if same else 0
                if lcp[i][j] != val:
                    return ''
        # check distinct count
        if cur > 26:
            return ''
        # assign letters
        return ''.join(chr(ord('a') + x) for x in pattern[:cur])

