class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        top = {0}
        for x in toppingCosts*2: 
            top |= {x + xx for xx in top}
        top = sorted(top)

        ans = inf 
        for bc in baseCosts: 
            k = bisect_left(top, target - bc)
