class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # build a Trie of forbidden strings
        trie = {}
        for f in forbidden:
            t = trie
            for ch in f:
                t = t.setdefault(ch, {})
