class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        dp = [1] * (n + 1)          # dp[j] = #valid permutations of length i ending with value j
        for ch in s:
            new = [0] * (len(dp) - 1)
            if ch == 'D':
                suffix = 0
                for j in range(len(dp) - 1, -1, -1):
                    suffix = (suffix + dp[j]) % MOD
                    new[j] = suffix
            else:  # 'I'
                prefix = 0
                for j in range(len(dp)):
                    prefix = (prefix + dp[j]) % MOD
                    new[j] = prefix
            dp = new
        return dp[0] % MOD

