class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # build a trie of forbidden words
        trie = {}
        for f in forbidden:
            t = trie
            for ch in f:
                t = t.setdefault(ch, {})
            t["#"] = True

        # check if a string contains any forbidden word
        def contains_forbidden(s: str) -> bool:
            for i in range(len(s)):
                t = trie
                for c in s[i:]:
                    if c not in t:
                        break
                    t = t[c]
                    if "#" in t:
                        return True
            return False

        # sliding window to find longest allowed substring
        left = 0
        ans = 0
        for right in range(len(word)):
            while contains_forbidden(word[left:right + 1]):
                left += 1
            ans = max(ans, right - left + 1)
        return ans

