class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        @lru_cache(None)
        def dp(i, rem):
            if i == len(toppingCosts) or rem < 0:
                return 0
            skip = dp(i+1, rem)
            take = toppingCosts[i] + dp(i+1, rem - toppingCosts[i])
            return min((skip, take), key=lambda y: (abs(y - rem), y))
        ans = float('inf')
        for bc in baseCosts:
            ans = min((ans, bc + dp(0, target - bc)), key=lambda x: (abs(x - target), x))
        return ans

