class Solution:
    def numPermsDISequence(self, s: str) -> int:
        mod = 10**9 + 7
        dp = [1]
        for c in s:
            ndp = [0] * (len(dp) + 1)
            if c == 'I':
                total = 0
                for j in range(len(dp)):
                    total = (total + dp[j]) % mod
                    ndp[j] = total
            else:  # 'D'
                total = 0
                for j in range(len(dp) - 1, -1, -1):
                    total = (total + dp[j]) % mod
                    ndp[j + 1] = total
            dp = ndp
        return dp[0] % mod

