class Solution:
    def closestCost(self, baseCosts, toppingCosts, target):
        from functools import lru_cache

        @lru_cache(None)
        def dfs(i, rem):
            if i == len(toppingCosts):
                return 0
            take = dfs(i + 1, rem - toppingCosts[i])
            skip = dfs(i + 1, rem)
            return min((take, skip), key=lambda v: (abs(v - rem), v))

        best = float('inf')
        for bc in baseCosts:
            cur = min((dfs(0, target - bc), bc + dfs(0, target - bc)), 
                      key=lambda x: (abs(x - target), x))
            best = min((best, cur), key=lambda x: (abs(x - target), x))
        return best

