class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # if any character of s2 is missing in s1, answer is 0
        if not set(s2).issubset(set(s1)):
            return 0

        i = j = repeat = cnt = 0       # i: index in s1, j: index in s2
        cache = {}                       # key = (repeat, j) -> (repeat_idx, count_of_s2_sofar)
        while repeat < n1:
            for ch in s1:
                if ch == s2[j]:
                    j += 1
                    if j == len(s2):
                        cnt += 1        # one more full match of s2
                        j = 0
            repeat += 1
            key = (repeat, j)
            if key in cache:
                prev_repeat, prev_cnt = cache[key]
                cycle_len = repeat - prev_repeat
                cycle_cnt = cnt - prev_cnt
                remaining = n1 - repeat
                cnt += (remaining // cycle_len) * cycle_cnt
                break
            else:
                cache[key] = (repeat, cnt)

        # cnt is total number of times s2 appears in the constructed string
        return cnt // n2

