    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        repeat, idx = 0, 0
        first_occurrence = {}
        while repeat < n1:
            for ch in s1:
                if ch == s2[idx]:
                    idx += 1
                    if idx == len(s2):
                        repeat += 1
                        idx = 0
            key = (repeat, idx)
            if key in first_occurrence:
