                cycle_len = repeat - prev_repeat
                cycles = (n1 - prev_repeat) // cycle_len
                remain = (n1 - prev_repeat) % cycle_len
                total_repeats = repeat + cycles * cycle_len + remain
                return total_repeats // n2
            else:
                first_occurrence[key] = (repeat, idx)
        return repeat // n2

