class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a trie of all forbidden substrings
        trie = {}
        for f in forbidden:
            node = trie
            for ch in f:
                node = node.setdefault(ch, {})
            node["end"] = True

        n = len(word)
        max_len = 0
        start = 0

        for end in range(n):
            # Check if the substring ending at `end` contains a forbidden word.
            # If it does, move `start` right after the forbidden occurrence.
            node = trie
            for k in range(end, start-1, -1):
                ch = word[k]
                if ch not in node:
                    break
                node = node[ch]
                if "end" in node:
                    start = k + 1
                    break
            max_len = max(max_len, end - start + 1)
        return max_len

