class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        m, n = len(pizza), len(pizza[0])
        mod = 10**9 + 7
        # apple prefix sum
        pre = [[0]*(n+1) for _ in range(m+1)]
        for i in range(m):
            for j in range(n):
                pre[i+1][j+1] = pre[i][j+1] + pre[i+1][j] - pre[i][j] + (pizza[i][j]=='A')
        from functools import lru_cache

        @lru_cache(None)
        def dfs(r1, c1, k):
            if k == 1:
                # check if any apple remains in current subpizza
                apples = pre[m][n] - pre[r1][n] - pre[m][c1] + pre[r1][c1]
                return 1 if apples else 0
            res = 0
            # horizontal cuts
            for r in range(r1, m):
                # apples in top part rows r1..r-1
                apples = pre[r][n] - pre[r1][n] - pre[r][c1] + pre[r1][c1]
                if apples:
                    res += dfs(r, c1, k-1)
            # vertical cuts
            for c in range(c1, n):
                apples = pre[m][c+1] - pre[r1][c+1] - pre[m][c1] + pre[r1][c1]
                if apples:
                    res += dfs(r1, c, k-1)
            return res % mod

        total = pre[m][n]
        if total < k:
            return 0
        return dfs(0,0,k) % mod

