class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        if Counter(s) != Counter(t):
            return False
        pos = defaultdict(deque)
        for j, ch in enumerate(t):
            pos[ch].append(j)
        a = [pos[c].popleft() for c in s]
        bit = BIT(len(a))
        last = defaultdict(lambda: -1)
        for i, idx in enumerate(a):
