class Solution:
    def construct(self, grid: List[List[int]]) -> 'Node':
        return self._build(grid, 0, 0, len(grid))

    def _build(self, grid, row, col, size):
        if size == 1:
            return Node(grid[row][col], True)
        half = size // 2
        tl = self._build(grid, row, col, half)
        tr = self._build(grid, row, col + half, half)
        bl = self._build(grid, row + half, col, half)
        br = self._build(grid, row + half, col + half, half)
        if all(child.isLeaf and child.val == tl.val for child in (tl, tr, bl, br)):
            return Node(tl.val, True)
        return Node(tl.val, False, tl, tr, bl, br)

