class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # build a trie of forbidden words
        trie = {}
        for f in forbidden:
            node = trie
            for ch in f:
                node = node.setdefault(ch, {})
            node["end"] = True

        # check if a string contains any forbidden substring
        def is_forbidden(s: str) -> bool:
            node = trie
            for ch in s:
                if ch not in node:
                    return False
                node = node[ch]
                if "end" in node:
                    return True
            return False

        # sliding window to keep the longest valid substring
        left = 0
        max_len = 0
        for right, ch in enumerate(word):
            # shrink window until it becomes valid again
            while is_forbidden(word[left:right + 1]):
                left += 1
            max_len = max(max_len, right - left + 1)
        return max_len

