from functools import lru_cache
from typing import List

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        m, n = len(pizza), len(pizza[0])
        MOD = 10**9 + 7
        # prefix sum of apples
        pref = [[0]*(n+1) for _ in range(m+1)]
        for i in range(m):
            for j in range(n):
                pref[i+1][j+1] = pref[i][j+1] + pref[i+1][j] - pref[i][j] + (pizza[i][j] == 'A')

        def apples(r1, c1, r2, c2):
            return pref[r2][c2] - pref[r1][c2] - pref[r2][c1] + pref[r1][c1]

        @lru_cache(None)
        def dfs(r, c, cuts):
            # count ways to cut pizza[r:,c:] into cuts pieces
            if cuts == 1:
                return 1 if apples(r, c, m, n) > 0 else 0
            total = 0
            # horizontal cuts
            for nr in range(r+1, m):
                if apples(r, c, nr, n) > 0:
                    total += dfs(nr, c, cuts-1)
            # vertical cuts
            for nc in range(c+1, n):
                if apples(r, c, m, nc) > 0:
                    total += dfs(r, nc, cuts-1)
            return total % MOD

        return dfs(0, 0, k) % MOD

