from typing import List

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        R, C = len(pizza), len(pizza[0])
        # 2‑D prefix sum of 'A's
        pre = [[0] * (C + 1) for _ in range(R + 1)]
        for i in range(R):
            for j in range(C):
                pre[i + 1][j + 1] = (
                    pre[i][j + 1] + pre[i + 1][j] -
                    pre[i][j] + (pizza[i][j] == 'A')
                )

        @lru_cache(None)
        def dfs(r1: int, c1: int, pieces: int) -> int:
            # apples in the current sub‑pizza
            apples = pre[R][C] - pre[r1][C] - pre[R][c1] + pre[r1][c1]
            if apples == 0:
                return 0
            if pieces == 1:
                return 1
            ans = 0
            # try horizontal cuts
            for i in range(r1 + 1, R):
                top_apples = pre[i][C] - pre[r1][C] - pre[i][c1] + pre[r1][c1]
                if top_apples == 0:
                    continue
                ans += dfs(i, c1, pieces - 1)
            # try vertical cuts
            for j in range(c1 + 1, C):
                left_apples = pre[R][j] - pre[r1][j] - pre[R][c1] + pre[r1][c1]
                if left_apples == 0:
                    continue
                ans += dfs(r1, j, pieces - 1)
            return ans % 1000000007

        return dfs(0, 0, k) % 1000000007

