class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        s1f = ''.join(c for c in s1 if c in s2)
        cnt = 0
        j = 0
        seen = {}
        for i in range(n1):
            for ch in s2:
                j = s1f.find(ch, j)
                if j == -1:
                    j = s1f.find(ch)
                    if j == -1:
                        return cnt // n2
                j += 1
            cnt += 1
            key = j % len(s1f) if s1f else 0
            if key in seen:
                prev_i, prev_cnt = seen[key]
                cycle_i = i - prev_i
                cycle_cnt = cnt - prev_cnt
                remaining = n1 - prev_i
                cnt = prev_cnt + (remaining // cycle_i) * cycle_cnt
                i = prev_i + remaining % cycle_i
                break
            seen[key] = (i, cnt)
        return cnt // n2

