class Solution:
    def numberOfArithmeticSlices(self, nums: List[int]) -> int:
        from collections import defaultdict
        n = len(nums)
        if n < 3:
            return 0
        dp = [defaultdict(int) for _ in range(n)]
        total = 0
        for i in range(1, n):
            for j in range(i):
                diff = nums[i] - nums[j]
                cnt = dp[j][diff]
                dp[i][diff] += cnt + 1
                total += cnt
        return total

