class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        s1 = ''.join(c for c in s1 if c in s2)
        idx = {c: i for i, c in enumerate(s2)}
        ptr = 0
        cnt = 0
        repeats = {}
        for i in range(n1 * len(s1)):
            for ch in s1:
                if ch == s2[ptr % len(s2)]:
                    ptr += 1
                    if ptr % len(s2) == 0:
                        cnt += 1
            if ptr in repeats:
                prev_i, prev_cnt = repeats[ptr]
                repeat_len = i - prev_i + 1
                repeat_cnt = cnt - prev_cnt
                repeat_blocks = (n1 - prev_i) // repeat_len
                cnt += repeat_blocks * repeat_cnt
                rem = (n1 - prev_i) % repeat_len
                for _ in range(rem):
                    for ch in s1:
                        if ch == s2[ptr % len(s2)]:
                            ptr += 1
                            if ptr % len(s2) == 0:
                                cnt += 1
                break
            else:
                repeats[ptr] = i
        return cnt // n2

