from functools import lru_cache
from typing import List

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        toppingCosts *= 2  # allow using each topping twice

        @lru_cache(None)
        def dfs(i, remain):
            """Return the cost of toppings[i:] closest to remain."""
            if remain < 0 or i >= len(toppingCosts):
                return 0
            # either skip current topping or take it
            return min(
                dfs(i + 1, remain),
                toppingCosts[i] + dfs(i + 1, remain - toppingCosts[i]),
                key=lambda y: (abs(y - target), y)
            )

        best = float('inf')
        for bc in baseCosts:
            cand = bc + dfs(0, target - bc)
            best = min(best, cand, key=lambda y: (abs(y - target), y))
        return best

