from functools import lru_cache
from typing import List
import math

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        @lru_cache(None)
        def dfs(i, rem):
            if rem < 0 or i == len(toppingCosts):
                return 0
            skip = dfs(i + 1, rem)
            take = toppingCosts[i] + dfs(i + 1, rem - toppingCosts[i])
            return min((abs(skip - target), skip), (abs(take - target), take), key=lambda x: (x[0], x[1]))[1]

        best = math.inf
        for bc in baseCosts:
            cand = bc + dfs(0, target - bc)
            best = min((abs(cand - target), cand), (abs(best - target), best), key=lambda x: (x[0], x[1]))[1]
        return best

