from functools import lru_cache
from typing import List

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        MOD = 10**9 + 7
        m, n = len(pizza), len(pizza[0])
        pref = [[0]*(n+1) for _ in range(m+1)]
        for i in range(m):
            for j in range(n):
                pref[i+1][j+1] = pref[i][j+1] + pref[i+1][j] - pref[i][j] + (pizza[i][j] == 'A')

        @lru_cache(None)
        def dp(r, c, cuts):
            if cuts == 0:
                return 1 if pref[m][n] - pref[r][n] - pref[m][c] + pref[r][c] else 0
            ans = 0
            for nr in range(r+1, m):
                if pref[nr+1][n] - pref[nr][n] - pref[nr+1][c] + pref[nr][c]:
                    ans += dp(nr, c, cuts-1)
            for nc in range(c+1, n):
                if pref[m][nc+1] - pref[m][nc] - pref[r][nc+1] + pref[r][nc]:
                    ans += dp(r, nc, cuts-1)
            return ans % MOD

        return 0 if pref[m][n] < k else dp(0, 0, k-1)

