class Solution:
    def construct(self, grid: List[List[int]]) -> 'Node':
        if not grid: return None
        n = len(grid)
        return self._build(grid, 0, 0, n, n)

    def _build(self, grid, rs, cs, re, ce):
        if re - rs == 1:
            val = grid[rs][cs]
            return Node(val, True, None, None, None, None)
        node = Node(0, False, None, None, None, None)
        next_r = (re - rs) // 2
        node.topLeft = self._build(grid, rs, cs, rs + next_r, cs + next_r)
        node.topRight = self._build(grid, rs, cs + next_r, rs + next_r, ce)
        node.bottomLeft = self._build(grid, rs + next_r, cs, re, cs + next_r)
        node.bottomRight = self._build(grid, rs + next_r, cs + next_r, re, ce)
        # prune if children are leaves with same value
        if node.topLeft.isLeaf and node.topRight.isLeaf and node.bottomLeft.isLeaf and node.bottomRight.isLeaf and \
           node.topLeft.val == node.topRight.val == node.bottomLeft.val == node.bottomRight.val:
            child_val = node.topLeft.val
            return Node(child_val, True, None, None, None, None)
        return node

