from collections import defaultdict
class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        mem = {}
        def dfs(i, prev):
            if i == len(s):
                return 1
            if (i, prev) in mem:
                return mem[(i, prev)]
            total = 0
            if s[i] == 'D':
                for nxt in range(prev):
                    total = (total + dfs(i+1, nxt)) % MOD
            else:
                for nxt in range(prev+1, i+2):
                    total = (total + dfs(i+1, nxt)) % MOD
            mem[(i, prev)] = total
            return total
        return dfs(0, 0)

