from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a trie of forbidden substrings
        trie = {}
        for f in forbidden:
            node = trie
            for ch in f:
                node = node.setdefault(ch, {})
            node["end"] = True

        # Check whether a string contains any forbidden substring
        def contains_forbidden(s: str) -> bool:
            node = trie
            for ch in s:
                if ch not in node:
                    return False
                node = node[ch]
                if "end" in node:
                    return True
            return False

        max_len = 0
        left = 0
        # Expand the window with 'right' pointer
        for right, _ in enumerate(word):
            # Shrink from the left until the window is valid
            while contains_forbidden(word[left:right + 1]):
                left += 1
            # Update the maximum length of a valid substring
            max_len = max(max_len, right - left + 1)
        return max_len

