from functools import lru_cache
from typing import List

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        @lru_cache(None)
        def fn(i, x):
            """Return sum of subsequence of toppingCosts[i:] closest to x."""
            if x < 0 or i == len(toppingCosts):
                return 0
            # try skipping topping or taking it
            take = fn(i + 1, x - toppingCosts[i])
            skip = fn(i + 1, x)
            # choose closer to x, breaking ties by smaller sum
            return min((skip, take), key=lambda y: (abs(y - x), y))

        ans = float('inf')
        for bc in baseCosts:
            ans = min(
                ans,
                bc + fn(0, target - bc),
                key=lambda val: (abs(val - target), val)
            )
        return ans
